import sys


def sheet(cells: dict[str, str]) -> dict[str, int | str]:
    sys.setrecursionlimit(max(sys.getrecursionlimit(), 100000))
    memo: dict[str, int | str] = {}
    pending: set[str] = set()

    def fail(v):
        return isinstance(v, str)

    def trunc_div(a: int, b: int):
        if b == 0:
            return "#DIV/0!"
        q = abs(a) // abs(b)
        if (a < 0) != (b < 0):
            q = -q
        return q

    def tokenize(src: str):
        toks = []
        i = 0
        n = len(src)
        while i < n:
            ch = src[i]
            if ch.isspace():
                i += 1
                continue
            if ch.isdigit():
                j = i + 1
                while j < n and src[j].isdigit():
                    j += 1
                toks.append(("NUM", int(src[i:j])))
                i = j
                continue
            if ch.isalpha():
                j = i + 1
                while j < n and src[j].isalpha():
                    j += 1
                word = src[i:j]
                if word in ("SUM", "MIN", "MAX", "IF"):
                    toks.append(("FUNC", word))
                    i = j
                    continue
                k = j
                while k < n and src[k].isdigit():
                    k += 1
                toks.append(("CELL", src[i:k]))
                i = k
                continue
            if src.startswith("<>", i) or src.startswith("<=", i) or src.startswith(">=", i):
                toks.append(("CMP", src[i : i + 2]))
                i += 2
                continue
            if ch in "=<>":
                toks.append(("CMP", ch))
                i += 1
                continue
            if ch in "+-*/":
                toks.append(("OP", ch))
                i += 1
                continue
            toks.append(("SYM", ch))
            i += 1
        return toks

    def parse(src: str):
        toks = tokenize(src)
        pos = 0

        def peek(k=0):
            j = pos + k
            return toks[j] if j < len(toks) else None

        def pop():
            nonlocal pos
            t = toks[pos]
            pos += 1
            return t

        def parse_expr():
            node = parse_term()
            while peek() in (("OP", "+"), ("OP", "-")):
                op = pop()[1]
                rhs = parse_term()
                node = ("bin", op, node, rhs)
            return node

        def parse_term():
            node = parse_unary()
            while peek() in (("OP", "*"), ("OP", "/")):
                op = pop()[1]
                rhs = parse_unary()
                node = ("bin", op, node, rhs)
            return node

        def parse_unary():
            if peek() == ("OP", "-"):
                pop()
                return ("neg", parse_unary())
            return parse_primary()

        def parse_primary():
            t = peek()
            if t[0] == "NUM":
                return ("num", pop()[1])
            if t[0] == "CELL":
                return ("cell", pop()[1])
            if t == ("SYM", "("):
                pop()
                node = parse_expr()
                pop()
                return node
            return parse_func()

        def parse_func():
            name = pop()[1]
            pop()
            if name == "IF":
                left = parse_expr()
                op = pop()[1]
                right = parse_expr()
                pop()
                then_e = parse_expr()
                pop()
                else_e = parse_expr()
                pop()
                return ("IF", left, op, right, then_e, else_e)
            args = []
            while True:
                if peek() and peek()[0] == "CELL" and peek(1) == ("SYM", ":"):
                    c1 = pop()[1]
                    pop()
                    c2 = pop()[1]
                    args.append(("range", c1, c2))
                else:
                    args.append(parse_expr())
                if peek() == ("SYM", ","):
                    pop()
                    continue
                break
            pop()
            return (name, args)

        return parse_expr()

    def range_names(a: str, b: str):
        c1, r1 = ord(a[0]) - 65, int(a[1:])
        c2, r2 = ord(b[0]) - 65, int(b[1:])
        names = []
        for r in range(min(r1, r2), max(r1, r2) + 1):
            for c in range(min(c1, c2), max(c1, c2) + 1):
                name = chr(65 + c) + str(r)
                if name in cells:
                    names.append(name)
        return names

    def eval_node(node):
        tag = node[0]
        if tag == "num":
            return node[1]
        if tag == "cell":
            return eval_cell(node[1])
        if tag == "neg":
            v = eval_node(node[1])
            if fail(v):
                return v
            return -v
        if tag == "bin":
            op, left, right = node[1], node[2], node[3]
            lv = eval_node(left)
            if fail(lv):
                return lv
            rv = eval_node(right)
            if fail(rv):
                return rv
            if op == "+":
                return lv + rv
            if op == "-":
                return lv - rv
            if op == "*":
                return lv * rv
            return trunc_div(lv, rv)
        if tag == "IF":
            _, left, op, right, then_e, else_e = node
            lv = eval_node(left)
            if fail(lv):
                return lv
            rv = eval_node(right)
            if fail(rv):
                return rv
            if op == "=":
                cond = lv == rv
            elif op == "<>":
                cond = lv != rv
            elif op == "<":
                cond = lv < rv
            elif op == "<=":
                cond = lv <= rv
            elif op == ">":
                cond = lv > rv
            else:
                cond = lv >= rv
            return eval_node(then_e if cond else else_e)
        vals = []
        for arg in node[1]:
            if arg[0] == "range":
                for name in range_names(arg[1], arg[2]):
                    v = eval_cell(name)
                    if fail(v):
                        return v
                    vals.append(v)
            else:
                v = eval_node(arg)
                if fail(v):
                    return v
                vals.append(v)
        if tag == "SUM":
            return sum(vals)
        if not vals:
            return 0
        if tag == "MIN":
            return min(vals)
        return max(vals)

    def eval_cell(name: str):
        if name not in cells:
            return 0
        if name in memo:
            return memo[name]
        if name in pending:
            return "#CYCLE!"
        pending.add(name)
        raw = cells[name].strip()
        if raw.startswith("="):
            val = eval_node(parse(raw[1:]))
        else:
            val = int(raw)
        pending.remove(name)
        memo[name] = val
        return val

    return {name: eval_cell(name) for name in cells}
